import manifest from "@/assets/generated/manifest.json";

/**
 * Central image registry.
 *
 * `manifest.json` is generated by `tools/assets/build_images.py` and contains the
 * responsive variants that actually exist on disk. This file adds the human
 * layer — alt text, focal point, and default aspect ratio — so components never
 * hard-code `/assets/...` paths.
 */

export type ImageFormat = "webp" | "jpg" | "png";

interface ManifestVariant {
  w: number;
  h: number;
  src: Record<string, string>;
  bytes: Record<string, number>;
}

interface ManifestAsset {
  id: string;
  kind: "photo" | "logo";
  intrinsic: { w: number; h: number };
  dominantColor: string;
  variants: ManifestVariant[];
}

interface AssetPresentation {
  alt: string;
  /** CSS object-position, tuned to keep faces and marks in frame. */
  position?: string;
  /** Suggested aspect ratio for the default use of this image. */
  aspect?: number;
  /** Optional short label shown in admin media listings. */
  label?: string;
}

export interface ResolvedAsset {
  id: string;
  kind: "photo" | "logo";
  alt: string;
  position: string;
  aspect: number;
  width: number;
  height: number;
  dominantColor: string;
  variants: ManifestVariant[];
  src: string;
  webpSrcSet: string;
  fallbackSrcSet: string;
  bytes: number;
}

const PRESENTATION: Record<string, AssetPresentation> = {
  "profile.portrait": {
    alt: "Philemon Melabah in a studio portrait against a warm amber backdrop.",
    position: "50% 18%",
    aspect: 1044 / 1280,
    label: "Studio portrait",
  },
  "profile.portrait.square": {
    alt: "Close portrait of Philemon Melabah.",
    position: "50% 30%",
    aspect: 1,
    label: "Portrait square",
  },
  "profile.event": {
    alt: "Philemon Melabah at the Gospel Power conference wearing an event badge.",
    position: "50% 22%",
    aspect: 1024 / 1280,
    label: "Conference portrait",
  },
  "leadership.stage": {
    alt: "Philemon Melabah on stage at a Gospel Power event at UMaT.",
    position: "50% 30%",
    aspect: 433 / 576,
    label: "Event stage",
  },
  "projects.omnimarket.logo": {
    alt: "OmniMarket wordmark.",
    position: "50% 50%",
    aspect: 1280 / 431,
    label: "OmniMarket wordmark",
  },
};

const manifests = manifest.assets as unknown as Record<string, ManifestAsset>;

function buildSrcSet(
  variants: ManifestVariant[],
  format: ImageFormat,
): string {
  return variants
    .filter((variant) => variant.src[format])
    .map((variant) => `${variant.src[format]} ${variant.w}w`)
    .join(", ");
}

function resolve(id: string): ResolvedAsset | null {
  const entry = manifests[id];
  if (!entry) return null;

  const presentation = PRESENTATION[id] ?? {
    alt: "",
    position: "50% 50%",
  };
  const variants = [...entry.variants].sort((a, b) => a.w - b.w);
  const hasWebp = variants.some((variant) => variant.src.webp);
  const fallbackFormat: ImageFormat = hasWebp ? "jpg" : "png";
  const fallbackVariants = variants.filter((v) => v.src[fallbackFormat]);
  const usable = fallbackVariants.length > 0 ? fallbackVariants : variants;
  const largest = usable[usable.length - 1];

  if (!largest) return null;

  const fallbackSrc = largest.src[fallbackFormat] ?? largest.src.webp ?? "";

  return {
    id,
    kind: entry.kind,
    alt: presentation.alt,
    position: presentation.position ?? "50% 50%",
    aspect: presentation.aspect ?? entry.intrinsic.w / entry.intrinsic.h,
    width: largest.w,
    height: largest.h,
    dominantColor: entry.dominantColor,
    variants: usable,
    src: fallbackSrc,
    webpSrcSet: buildSrcSet(usable, "webp"),
    fallbackSrcSet: buildSrcSet(usable, fallbackFormat),
    bytes: usable.reduce((sum, variant) => sum + (variant.bytes.webp ?? 0), 0),
  };
}

export type ImageId =
  | "profile.portrait"
  | "profile.portrait.square"
  | "profile.event"
  | "leadership.stage"
  | "projects.omnimarket.logo";

const registry = new Map<string, ResolvedAsset>();
for (const id of Object.keys(manifests)) {
  const asset = resolve(id);
  if (asset) registry.set(id, asset);
}

export function getImage(id: ImageId): ResolvedAsset {
  const asset = registry.get(id);
  if (!asset) {
    throw new Error(`Unknown image asset: ${id}`);
  }
  return asset;
}

/** Safe lookup for records whose asset id comes from the CMS. */
export function findImage(id: string | null | undefined): ResolvedAsset | null {
  if (!id) return null;
  return registry.get(id) ?? null;
}

export function listImages(): ResolvedAsset[] {
  return [...registry.values()];
}

/** Manifest ids are the canonical reference used by media records. */
export function isRegistryId(value: string): value is ImageId {
  return registry.has(value);
}

export const SOCIAL_IMAGE = "/assets/social/og-image.jpg";
export const SOCIAL_IMAGE_ALT =
  "Philemon Melabah — full-stack developer, data and analytics, technology builder.";
